require 'thread'
require 'monitor'
require 'securerandom'
require 'bcrypt'

module AuthPool
  class ConnectionPool
    include MonitorMixin

    def initialize(size: 5)
      super()
      @size = size
      @connections = []
      @checked_out = {}
      @size.times { @connections << create_connection }
    end

    def checkout
      synchronize do
        conn = @connections.pop
        return nil unless conn
        @checked_out[Thread.current.object_id] = conn
        conn
      end
    end

    def checkin(conn)
      synchronize do
        @checked_out.delete(Thread.current.object_id)
        conn[:authenticated] = false
        conn[:user] = nil
        conn[:session] = nil
        @connections.push(conn)
      end
    end

    def with_connection
      conn = checkout
      raise "No available connections" unless conn
      yield conn
    ensure
      checkin(conn) if conn
    end

    private

    def create_connection
      { id: SecureRandom.hex(8), session: nil, authenticated: false, user: nil }
    end
  end

  class SessionStore
    def initialize
      @sessions = {}
      @mutex = Mutex.new
    end

    def create_session(user_id, roles)
      token = SecureRandom.hex(32)
      @mutex.synchronize do
        @sessions[token] = { user_id: user_id, roles: roles.frozen? ? roles : roles.dup.freeze, created_at: Time.now }
      end
      token
    end

    def validate_session(token)
      @mutex.synchronize do
        s = @sessions[token]
        s ? { user_id: s[:user_id], roles: s[:roles].dup, created_at: s[:created_at] } : nil
      end
    end

    def destroy_session(token)
      @mutex.synchronize { @sessions.delete(token) }
    end
  end

  class Authenticator
    def initialize(pool:, session_store:, user_repo:)
      @pool = pool
      @session_store = session_store
      @user_repo = user_repo
      @auth_callbacks = []
    end

    def on_auth_success(&block)
      @auth_callbacks << block
    end

    def authenticate(username, password)
      @pool.with_connection do |conn|
        user = @user_repo.find_by_username(username)
        return auth_failure(conn, "User not found") unless user

        unless BCrypt::Password.new(user[:password_hash]) == password
          return auth_failure(conn, "Invalid password")
        end

        conn[:authenticated] = true
        conn[:user] = user[:id]

        session_token = @session_store.create_session(user[:id], user[:roles])
        conn[:session] = session_token

        result = { success: true, token: session_token, user_id: user[:id] }

        notify_auth_success(result, user)

        result
      end
    end

    def authorize(token, required_role)
      session = @session_store.validate_session(token)
      return { authorized: false, reason: "Invalid session" } unless session

      if session[:roles].include?(required_role)
        { authorized: true, user_id: session[:user_id] }
      else
        { authorized: false, reason: "Insufficient privileges" }
      end
    end

    def elevate_privileges(token, target_role, admin_password)
      session = @session_store.validate_session(token)
      return { success: false, reason: "Invalid session" } unless session

      @pool.with_connection do |conn|
        admin = @user_repo.find_by_id(session[:user_id])
        return { success: false, reason: "User not found" } unless admin

        unless admin[:roles].include?("admin")
          return { success: false, reason: "Not an admin" }
        end

        unless BCrypt::Password.new(admin[:password_hash]) == admin_password
          return { success: false, reason: "Invalid admin password" }
        end

        conn[:authenticated] = true
        conn[:user] = admin[:id]
        updated_roles = (session[:roles] + [target_role]).uniq
        @session_store.destroy_session(token)
        new_token = @session_store.create_session(session[:user_id], updated_roles)
        conn[:session] = new_token

        { success: true, token: new_token, roles: updated_roles }
      end
    end

    private

    def notify_auth_success(result, user)
      @auth_callbacks.each do |callback|
        callback.call(result.dup, user, nil)
      end
    end

    def auth_failure(conn, reason)
      conn[:authenticated] = false
      conn[:user] = nil
      conn[:session] = nil
      { success: false, reason: reason }
    end
  end

  class UserRepository
    def initialize
      @users = {}
      @mutex = Mutex.new
    end

    def add_user(username, password, roles: ["user"])
      id = SecureRandom.uuid
      @mutex.synchronize do
        @users[id] = {
          id: id,
          username: username,
          password_hash: BCrypt::Password.create(password),
          roles: roles.freeze
        }
      end
      id
    end

    def find_by_username(username)
      @mutex.synchronize do
        @users.values.find { |u| u[:username] == username }
      end
    end

    def find_by_id(id)
      @mutex.synchronize { @users[id] }
    end

    def update_roles(id, roles)
      @mutex.synchronize do
        @users[id][:roles] = roles.freeze if @users[id]
      end
    end
  end
